(function(){var b=(window.ANNONCES||{}).banniere;if(!b||!b.active)return;var n=new Date();if(b.debut&&new Date(b.debut+'T00:00:00')>n)return;if(b.fin&&new Date(b.fin+'T23:59:59')<n)return;try{if(localStorage.getItem('lumiaBanniere|'+(b.titre||b.texte||'')+'|'+(b.debut||'')+'|'+(b.fin||'')))return}catch(e){}document.documentElement.classList.add('has-banniere')})();
